head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > M > getTabInfo]<br/>컴포넌트에 정의된 전체 Tab 페이지의 정보를 객체 배열로 반환합니다.",
    "validation" : [
        "deleteTab() 메소드로 Tab 페이지가 추가/제거 되면 Tab 페이지의 현재 위치 인덱스값(currentTabIndex)은 재설정됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        alwaysDraw : true,
    }

    let cList= $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_2.xml" style="height:160px" id="content2" alwaysDraw="true">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px;" initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getTabInfo_onclick = function (e) {      
    let arrTabInfo = target1.getTabInfo();

    wf_body_bottom.getObj("scwin").setReturnValue("objReturn : " + arrTabInfo);    

    for (var i=0; i < arrTabInfo.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].id : " + arrTabInfo[i].id);    
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].label : " + arrTabInfo[i].label);    
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].defaultTabIndex : " + arrTabInfo[i].defaultTabIndex);    
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].currentTabIndex : " + arrTabInfo[i].currentTabIndex);    
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].src : " + arrTabInfo[i].src);    
        wf_body_bottom.getObj("scwin").setReturnValue("arrTabInfo["+i+"].alwaysDraw : " + arrTabInfo[i].alwaysDraw);    
    }   
}



scwin.btn_addTab_onclick = async function (e) {
    let tabCount = target1.getTabCount();

    let id = "tabs" + (tabCount+1);

    let rowJSON = {};  

    await target1.addTab(id,  
        {   
            "label": "newTabs", 
            "title": "dataObject",                        
        }, 
        {   
            "src": "/sample/common_link/tabControl_link_2.xml",
            "frameMode" : "wframePreload",
            "scope" : true, 
            "alwaysDraw": true,
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        }
    );

    scwin.btn_getTabInfo_onclick();
};



scwin.btn_deleteTab_onclick = async function (e) {
	await target1.deleteTab(par_index.getText());
};
